import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.skillpilot.backend.ai.CoachStateProjection;
import com.skillpilot.backend.ai.CoachToolFacade;
import com.skillpilot.backend.api.FrontierGoal;
import com.skillpilot.backend.api.UnifiedLearnerStateResponse;
import com.skillpilot.backend.completion.AssessmentMaterialRevision;
import com.skillpilot.backend.connectors.claude.v1.mcp.*;
import com.skillpilot.backend.connectors.gemini.v1.mcp.*;
import com.skillpilot.backend.landscape.ExamData;
import com.skillpilot.backend.service.LearnerService;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import static org.mockito.Mockito.*;

public final class VerifyReleasedHeadings {
    static final ObjectMapper JSON = new ObjectMapper();
    static final String FIXTURE = "fixture";
    static final CoachStateProjection PROJECTION = new CoachStateProjection("https://skillpilot.com");
    static final List<String> IDS = List.of("bcc56921-7107-5f5f-b721-3d5e0d7e1cd9", "a8dc0290-9f80-5763-8943-e16b8d2aa860", "4ea1b93f-2dba-59ac-87ab-29af6c55cc37");
    static String hash(String text) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));
    }
    static void check(boolean yes,String reason) {if (!yes) throw new AssertionError(reason);}
    static void wire(Object obj,String name,Object value) throws Exception {
        var field=obj.getClass().getDeclaredField(name);field.setAccessible(true);field.set(obj,value);
    }
    static JsonNode exam(JsonNode catalog,String id) {
        for (var goal:catalog.required("goals")) if (goal.required("id").asText().equals(id)) return goal.required("examData");
        throw new AssertionError(id);
    }
    static CoachToolFacade facade(String id,ExamData exam) throws Exception {
        var active=mock(FrontierGoal.class);when(active.id()).thenReturn(id);when(active.nodeKind()).thenReturn("exam");when(active.examData()).thenReturn(exam);
        var state=mock(UnifiedLearnerStateResponse.class);when(state.skillpilotId()).thenReturn(FIXTURE);when(state.activeGoal()).thenReturn(active);
        var learner=mock(LearnerService.class);when(learner.getCoachLearnerState(FIXTURE)).thenReturn(state);
        var coach=mock(CoachToolFacade.class,CALLS_REAL_METHODS);wire(coach,"learnerService",learner);wire(coach,"coachStateProjection",PROJECTION);
        doReturn(state).when(coach).getLearnerState(FIXTURE);return coach;
    }
    static Object adapter(boolean claude,CoachToolFacade coach) throws Exception {
        Object instance;
        Object projector;
        if (claude) {
            var session=mock(ClaudeV1SessionCoordinator.class);
            when(session.read(eq(FIXTURE),any())).thenAnswer(call -> {
                Function<ClaudeV1SessionCoordinator.ReadContext,Object> read=call.getArgument(1);
                return new ClaudeV1SessionCoordinator.Outcome<>(read.apply(new ClaudeV1SessionCoordinator.ReadContext(FIXTURE,FIXTURE,1,"de",false,null)),1);
            });
            instance=mock(ClaudeV1McpContractAdapter.class,CALLS_REAL_METHODS);
            projector=mock(ClaudeV1CoachContextProjector.class,CALLS_REAL_METHODS);
            wire(instance,"sessionCoordinator",session);wire(instance,"capabilityService",mock(ClaudeV1CapabilityService.class));
        } else {
            var session=mock(GeminiV1SessionCoordinator.class);
            when(session.read(eq(FIXTURE),any())).thenAnswer(call -> {
                Function<GeminiV1SessionCoordinator.ReadContext,Object> read=call.getArgument(1);
                return new GeminiV1SessionCoordinator.Outcome<>(read.apply(new GeminiV1SessionCoordinator.ReadContext(FIXTURE,FIXTURE,1,"de")),1);
            });
            instance=mock(GeminiV1McpContractAdapter.class,CALLS_REAL_METHODS);
            projector=mock(GeminiV1CoachContextProjector.class,CALLS_REAL_METHODS);
            wire(instance,"sessionCoordinator",session);wire(instance,"capabilityService",mock(GeminiV1CapabilityService.class));
        }
        wire(projector,"coachStateProjection",PROJECTION);wire(instance,"contextProjector",projector);wire(instance,"coachToolFacade",coach);return instance;
    }
    record Delivered(String german,String english,JsonNode steps) {}
    static Delivered evaluate(Object provider,String id,String language,ExamData exam,JsonNode raw) throws Exception {
        var handler=provider.getClass().getDeclaredMethod("getExamEvaluation",String.class,Map.class);handler.setAccessible(true);
        var actual=(Map<?,?>)handler.invoke(provider,FIXTURE,Map.of("goalId",id,"language",language));
        check(id.equals(actual.get("goalId")),"goal");String de=(String)actual.get("solutionContent"),en=(String)actual.get("solutionContentEn");
        check(de.equals(PROJECTION.projectReleasedEvaluationContent(exam.getSolutionContent())),"German material");
        check(en.equals(PROJECTION.projectReleasedEvaluationContent(exam.getSolutionContentEn())),"English material");
        var score=(CoachToolFacade.ExamScoring)actual.get("scoring");var rows=raw.required("scoring").required("steps");
        check(score.maxPoints()==exam.getScoring().getMaxPoints() && score.passingPoints()==exam.getScoring().getPassingPoints(),"threshold");
        check(score.steps().size()==rows.size(),"step count");
        for (int n=0;n<rows.size();n++) {
            var nativeStep=score.steps().get(n);var stored=rows.get(n);
            check(nativeStep.id().equals(stored.required("id").asText()) && nativeStep.points()==stored.required("points").asDouble() && nativeStep.description().equals(stored.required("description").asText()),"step "+n);
        }
        return new Delivered(de,en,JSON.valueToTree(score.steps()));
    }
    static String[] headings(String id,boolean english) {
        if (id.startsWith("bcc56921")) return english ? new String[]{"### Marking (author candidate, 24 November 2026, review decision pending)","### Marking"} : new String[]{"### Bewertung (Autorenkandidat 24.11.2026, Prüfentscheid offen)","### Bewertung"};
        boolean revised=id.startsWith("a8dc0290");
        return english ? new String[]{"**Partial credit ("+(revised?"revised author candidate":"author candidate")+", 24 November 2026):**","**Partial credit:**"} : new String[]{"**Teilpunktbewertung ("+(revised?"überarbeiteter Autorenkandidat":"Autorenkandidat")+", 24.11.2026):**","**Teilpunktbewertung:**"};
    }
    static void onlyHeading(String before,String after,String[] changes) {
        int first=before.indexOf(changes[0]);check(first>=0 && first==before.lastIndexOf(changes[0]),"old heading count");
        check(before.replace(changes[0],changes[1]).equals(after) && after.lines().filter(line -> line.startsWith(changes[1])).count()==1,"heading-only change");
    }
    public static void main(String[] args) throws Exception {
        var catalogs=List.of(JSON.readTree(Path.of(args[0]).toFile()),JSON.readTree(Path.of(args[1]).toFile()));var output=JSON.createArrayNode();
        for (String id:IDS) {
            ObjectNode row=output.addObject();row.put("goalId",id);var revisions=row.putObject("materialRevisions");var results=row.putObject("providers");
            var old=exam(catalogs.get(0),id);var current=exam(catalogs.get(1),id);
            var copy=old.deepCopy();var before=(ObjectNode)copy;for (boolean en:List.of(false,true)) {String key=en?"solutionContentEn":"solutionContent";onlyHeading(old.required(key).asText(),current.required(key).asText(),headings(id,en));before.set(key,current.required(key));}
            check(before.equals(current),"other exam field changed");
            ExamData oldExam=JSON.treeToValue(old,ExamData.class),newExam=JSON.treeToValue(current,ExamData.class);
            var prev=AssessmentMaterialRevision.of(oldExam);var next=AssessmentMaterialRevision.of(newExam);
            check(!prev.taskRevision().equals(next.taskRevision()) && prev.rubricRevision().equals(next.rubricRevision()) && !prev.fingerprint().equals(next.fingerprint()),"unexpected revision identity");
            revisions.set("prior",JSON.valueToTree(prev));revisions.set("current",JSON.valueToTree(next));
            for (boolean claude:List.of(true,false)) {
                var label=claude?"Claude":"Gemini";var provider=results.putObject(label);var predecessor=adapter(claude,facade(id,oldExam));var successor=adapter(claude,facade(id,newExam));
                for (String language:List.of("de","en")) {
                    var previous=evaluate(predecessor,id,language,oldExam,old);var active=evaluate(successor,id,language,newExam,current);
                    onlyHeading(previous.german(),active.german(),headings(id,false));onlyHeading(previous.english(),active.english(),headings(id,true));check(previous.steps().equals(active.steps()),"projected steps changed");
                    var actual=provider.putObject(language);actual.put("previousGermanSha256",hash(previous.german()));actual.put("germanSha256",hash(active.german()));actual.put("previousEnglishSha256",hash(previous.english()));actual.put("englishSha256",hash(active.english()));actual.put("stepCount",active.steps().size());actual.put("orderedNativeStepsJsonSha256",hash(active.steps().toString()));
                }
            }
        }
        System.out.println(JSON.writerWithDefaultPrettyPrinter().writeValueAsString(output));
    }
}
